-- VERIFIKASI HASIL SEED DATA
-- ==============================================================================
-- Jalankan query berikut untuk memverifikasi data yang baru saja dimasukkan:
-- SELECT COUNT(*) AS total_produk FROM products WHERE is_active = true;
-- SELECT COUNT(*) AS total_batch FROM stock_batches WHERE qty_remaining > 0;
-- SELECT COUNT(*) AS total_tiers FROM price_tiers;
